def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers = list(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    # --- Helpers ---
    def route_load(r):
        s = 0
        for v in r:
            s += demands[v]
        return s

    def route_cost(r):
        if not r:
            return 0
        c = matrix[depot][r[0]]
        for i in range(len(r) - 1):
            c += matrix[r[i]][r[i + 1]]
        c += matrix[r[-1]][depot]
        return c

    def total_cost(routes):
        return sum(route_cost(r) for r in routes)

    # --- Savings-style deterministic construction (capacity-feasible) ---
    # Each customer starts as a route [i]
    routes = [[i] for i in customers]
    route_of = {}
    for r in routes:
        for v in r:
            route_of[v] = r

    loads = {id(r): route_load(r) for r in routes}

    # Precompute savings for pairs; include tie-breaking with indices for determinism
    # Only compute for unique pairs i<j
    cust_set = set(customers)
    pairs = []
    for idx_i in range(len(customers)):
        i = customers[idx_i]
        for idx_j in range(idx_i + 1, len(customers)):
            j = customers[idx_j]
            if i in cust_set and j in cust_set:
                s = matrix[depot][i] + matrix[depot][j] - matrix[i][j]
                pairs.append((s, i, j))
    pairs.sort(key=lambda x: (-x[0], x[1], x[2]))

    def same_route(a, b):
        return route_of.get(a) is route_of.get(b)

    # merge only if routes are different and endpoints are compatible
    # We'll maintain references; merging removes one route and mutates the other.
    active = {id(r): True for r in routes}

    for _, i, j in pairs:
        ri = route_of.get(i)
        rj = route_of.get(j)
        if ri is None or rj is None:
            continue
        if ri is rj:
            continue
        if not active.get(id(ri), False) or not active.get(id(rj), False):
            continue

        # identify positions: i must be at an end of ri; j must be at an end of rj
        ri0, ri1 = ri[0], ri[-1]
        rj0, rj1 = rj[0], rj[-1]

        # capacity check
        li = loads.get(id(ri), route_load(ri))
        lj = loads.get(id(rj), route_load(rj))
        if li + lj > capacity:
            continue

        merged = None
        # Four possible endpoint combinations:
        # ri end i + rj start j  => ri + rj
        if ri1 == i and rj0 == j:
            merged = ri + rj
        # ri start i + rj end j => reverse ri + rj? Actually need i at start and j at end with concatenation:
        # If ri0==i, ri must be reversed to make i at end, then append rj
        elif ri0 == i and rj0 == j:
            merged = list(reversed(ri)) + rj
        # ri end i + rj end j => append reversed rj
        elif ri1 == i and rj1 == j:
            merged = ri + list(reversed(rj))
        # ri start i + rj end j => reverse ri and append reversed rj? make i end and j start by reversing rj
        elif ri0 == i and rj1 == j:
            merged = list(reversed(ri)) + list(reversed(rj))

        if merged is None:
            continue

        # Accept merge; update route_of for moved nodes, deactivate rj
        active[id(ri)] = True
        active[id(rj)] = False
        routes.append(merged)  # keep history but inactive ones won't be used; still need route_of correctness
        for v in merged:
            route_of[v] = merged
        # Deactivate old routes in route_of by overwrite above; now update loads
        loads[id(merged)] = li + lj
        # Also remove references from route_of by ensuring endpoints map to merged route for their nodes (done)
        # Mark ri and rj as inactive
        active[id(ri)] = False
        active[id(rj)] = False
        # Ensure we don't keep too many inactive routes: optionally reuse merged as ri reference is hard,
        # but construction ends fast; local search will rebuild using route_of.
        # We'll just stop using inactive routes by reconstructing at end.

    # Rebuild active route list from route_of mapping (each node points to final merged route)
    final_routes_map = {}
    for v in customers:
        r = route_of.get(v)
        if r is None:
            continue
        final_routes_map[id(r)] = r
    routes = [r for _, r in final_routes_map.items()]

