                best_delta = None
                for pos in range(len(r)):
                    v = r[pos]
                    # delta: cost(r) - cost(r_without_v) approximately by recomputing local neighborhood
                    if len(r) == 1:
                        delta = matrix[depot][v] * 2
                    else:
                        a = depot if pos == 0 else r[pos - 1]
                        b = depot if pos == len(r) - 1 else r[pos + 1]
                        delta = matrix[a][v] + matrix[v][b] - matrix[a][b]
                    # we want to remove customer with largest contribution to route cost per unit demand
                    key = (delta / max(1, demands[v]), delta, v)
                    if best_pos is None or key > best_delta:
                        best_pos = pos
                        best_delta = key
                rem = r.pop(best_pos)
                # insert rem into best feasible route by cheapest increase, else make new route
                best_route = None
                best_cost = None
