                    if route_load(rr) + demands[rem] > capacity:
                        continue
                    # try best insertion position in rr (deterministic)
                    # compute insertion cost increase over depot-rr-depot edges
                    if not rr:
                        inc = matrix[depot][rem] * 2
                        if best_cost is None or inc < best_cost or (inc == best_cost and id(rr) < id(best_route) if best_route else True):
                            best_cost = inc
                            best_route = rr
                    else:
