def solve_cvrp(instance):
    depot = instance["depot_index"]
    customers_set = set(instance["customer_ids"])
    demands = instance["demands"]
    capacity = instance["capacity"]
    matrix = instance["distance_matrix"]

    def route_load(rt):
        s = 0
        for n in rt:
            s += demands[n]
        return s

    def route_cost(rt):
        if not rt:
            return 0
        c = matrix[depot][rt[0]]
        for i in range(len(rt) - 1):
            c += matrix[rt[i]][rt[i + 1]]
        c += matrix[rt[-1]][depot]
        return c

    def total_cost(routes):
        s = 0
        for r in routes:
            s += route_cost(r)
        return s

    # --- Initial constructive: greedy with depot-return aware criterion ---
    routes = []
    customers = customers_set
    while customers:
        route = []
        load = 0
        current = depot
        while True:
            feasible = []
            for node in customers:
                if load + demands[node] <= capacity:
                    feasible.append(node)
            if not feasible:
                break
            nxt = min(feasible, key=lambda node: (matrix[current][node] + matrix[node][depot], demands[node], node))
            route.append(nxt)
            customers.remove(nxt)
            load += demands[nxt]
            current = nxt
        routes.append(route)

    # --- Targeted deterministic improvements ---
    # 1) Route merge at ends (now with reversed orientations too)
    improved = True
    while improved:
        improved = False
        best_move = None
        best_delta = 0

        def first_last(rt, rev):
            if not rt:
                return None, None
            if not rev:
                return rt[0], rt[-1]
            return rt[-1], rt[0]

        # Consider merging i + j with orientations (rev_i, rev_j) and concatenation end_i -> start_j
        # old boundary: depot->end_i + start_j->depot
        # new boundary: depot->start_i + end_i->start_j + end_j->depot (but depot->start_i and end_j->depot are unchanged)
        # Since depot links unchanged for the concatenated route except replaced edge, the delta is:
        # delta = matrix[end_i][start_j] - matrix[depot][end_i] - matrix[start_j][depot]
        # (because old had depot->end_i and start_j->depot as the connections to depot for the two separate routes)
        for i in range(len(routes)):
            r1 = routes[i]
            if not r1:
                continue
            load1 = route_load(r1)
            for j in range(len(routes)):
                if i == j:
                    continue
                r2 = routes[j]
                if not r2:
                    continue
                load2 = route_load(r2)
                if load1 + load2 > capacity:
                    continue

                for rev_i in (0, 1):
                    s1, e1 = first_last(r1, rev_i)
                    if s1 is None:
                        continue
                    for rev_j in (0, 1):
                        s2, e2 = first_last(r2, rev_j)
                        if s2 is None:
                            continue
                        delta = matrix[e1][s2] - matrix[depot][e1] - matrix[s2][depot]
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (i, j, rev_i, rev_j)

        if best_move is not None and best_delta < 0:
            i, j, rev_i, rev_j = best_move
            ri = routes[i]
            rj = routes[j]
            if rev_i:
                ri = ri[::-1]
            if rev_j:
                rj = rj[::-1]
            new_route = ri + rj
            if i < j:
                routes.pop(j)
                routes.pop(i)
            else:
                routes.pop(i)
                routes.pop(j)
            routes.append(new_route)
            improved = True

    # 2) Deterministic 2-opt within each route
    def two_opt_on_route(rt):
        n = len(rt)
        if n < 4:
            return rt, False
        best_impr = 0
        best = None
        for i in range(1, n - 2):
            a = rt[i - 1]
            b = rt[i]
            for j in range(i + 1, n - 1):
                c = rt[j]
                d = rt[j + 1]
                old = matrix[a][b] + matrix[c][d]
                new = matrix[a][c] + matrix[b][d]
                delta = new - old
                if delta < best_impr:
                    best_impr = delta
                    best = (i, j)
        if best is not None:
            i, j = best
            rt2 = rt[:i] + rt[i:j + 1][::-1] + rt[j + 1:]
            return rt2, True
        return rt, False

    changed = True
    while changed:
        changed = False
        # 2-opt sweep until no improvements in a full pass
        for idx in range(len(routes)):
            r = routes[idx]
            r2, ok = two_opt_on_route(r)
            if ok:
                routes[idx] = r2
                changed = True

        if changed:
            continue

        # 3) Deterministic relocate: move one node from one route to another best position
        best_move = None
        best_delta = 0

        loads = [route_load(r) for r in routes]
        for ri in range(len(routes)):
            r1 = routes[ri]
            if not r1:
                continue
            load1 = loads[ri]
            for k in range(len(r1)):
                node = r1[k]
                demand = demands[node]
                prev = depot if k == 0 else r1[k - 1]
                nxt = depot if k == len(r1) - 1 else r1[k + 1]
                old_remove = matrix[prev][node] + matrix[node][nxt]

                for rj in range(len(routes)):
                    if rj == ri:
                        continue
                    r2 = routes[rj]
                    if not r2:
                        continue
                    load2 = loads[rj]
                    if load2 + demand > capacity:
                        continue

                    # insertion between p-1 and p, p in [0..len(r2)]
                    for p in range(len(r2) + 1):
                        ins_prev = depot if p == 0 else r2[p - 1]
                        ins_nxt = depot if p == len(r2) else r2[p]
                        old_ins = matrix[ins_prev][ins_nxt]
                        new_ins = matrix[ins_prev][node] + matrix[node][ins_nxt]
                        # removal delta: prev->nxt replaces prev->node->nxt
                        delta_remove = matrix[prev][nxt] - old_remove
                        delta_ins = new_ins - old_ins
                        delta = delta_remove + delta_ins
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (ri, k, rj, p)

        if best_move is not None and best_delta < 0:
            ri, k, rj, p = best_move
            r1 = routes[ri]
            node = r1[k]
            r1_new = r1[:k] + r1[k + 1:]
            if not r1_new:
                routes.pop(ri)
                if rj > ri:
                    rj -= 1
            else:
                routes[ri] = r1_new
            r2 = routes[rj]
            routes[rj] = r2[:p] + [node] + r2[p:]
            changed = True

    # Ensure no empty routes and feasibility
    final_routes = []
    for r in routes:
        if r:
            if route_load(r) <= capacity:
                final_routes.append(r)
            else:
                split = []
                cur = []
                load = 0
                for n in r:
                    if load + demands[n] <= capacity:
                        cur.append(n)
                        load += demands[n]
                    else:
                        split.append(cur)
                        cur = [n]
                        load = demands[n]
                if cur:
                    split.append(cur)
                for sr in split:
                    if sr and route_load(sr) <= capacity:
                        final_routes.append(sr)

    return final_routes
